// ActivityLog An event returned by the Activity Logs API.
type ActivityLog struct {
	// Action The task or activity the actor performed.
	Action ActivityLog_Action `json:"action"`

	// Actor The user who performed the action.
	Actor *ActivityLog_Actor `json:"actor"`

	// Context Contextual information about the event.
	Context ActivityLog_Context `json:"context"`

	// Entity The resource the actor took the action on. It can be a user, file, project or other resource types.
	Entity ActivityLog_Entity `json:"entity"`

	// ID The ID of the event.
	ID string `json:"id"`

	// Timestamp The timestamp of the event in seconds since the Unix epoch.
	Timestamp float32 `json:"timestamp"`
}

// ActivityLog_Action The task or activity the actor performed.
type ActivityLog_Action struct {
	// Details Metadata of the action. Each action type supports its own metadata attributes.
	Details *map[string]interface{} `json:"details"`

	// Type The type of the action.
	Type string `json:"type"`
}

// ActivityLogActorType The type of the user.
type ActivityLogActorType string

// ActivityLog_Actor The user who performed the action.
type ActivityLog_Actor struct {
	// Email The email of the user.
	Email *string `json:"email,omitempty"`

	// ID The ID of the user.
	ID *string `json:"id,omitempty"`

	// Name The name of the user. For SCIM events, the value is "SCIM Provider". For official support actions, the value is "Figma Support".
	Name string `json:"name"`

	// Type The type of the user.
	Type *ActivityLogActorType `json:"type,omitempty"`
}

// ActivityLog_Context Contextual information about the event.
type ActivityLog_Context struct {
	// ClientName The third-party application that triggered the event, if applicable.
	ClientName *string `json:"client_name"`

	// IPAddress The IP address from of the client that sent the event request.
	IPAddress string `json:"ip_address"`

	// IsFigmaSupportTeamAction If Figma's Support team triggered the event. This is either true or false.
	IsFigmaSupportTeamAction bool `json:"is_figma_support_team_action"`

	// OrgID The id of the organization where the event took place.
	OrgID string `json:"org_id"`

	// TeamID The id of the team where the event took place -- if this took place in a specific team.
	TeamID *string `json:"team_id"`
}

