func (t Node) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Node) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "BOOLEAN_OPERATION":
		return t.AsBooleanOperationNode()
	case "CANVAS":
		return t.AsCanvasNode()
	case "COMPONENT":
		return t.AsComponentNode()
	case "COMPONENT_SET":
		return t.AsComponentSetNode()
	case "CONNECTOR":
		return t.AsConnectorNode()
	case "DOCUMENT":
		return t.AsDocumentNode()
	case "ELLIPSE":
		return t.AsEllipseNode()
	case "EMBED":
		return t.AsEmbedNode()
	case "FRAME":
		return t.AsFrameNode()
	case "GROUP":
		return t.AsGroupNode()
	case "INSTANCE":
		return t.AsInstanceNode()
	case "LINE":
		return t.AsLineNode()
	case "LINK_UNFURL":
		return t.AsLinkUnfurlNode()
	case "RECTANGLE":
		return t.AsRectangleNode()
	case "REGULAR_POLYGON":
		return t.AsRegularPolygonNode()
	case "SECTION":
		return t.AsSectionNode()
	case "SHAPE_WITH_TEXT":
		return t.AsShapeWithTextNode()
	case "SLICE":
		return t.AsSliceNode()
	case "STAR":
		return t.AsStarNode()
	case "STICKY":
		return t.AsStickyNode()
	case "TABLE":
		return t.AsTableNode()
	case "TABLE_CELL":
		return t.AsTableCellNode()
	case "TEXT":
		return t.AsTextNode()
	case "TEXT_PATH":
		return t.AsTextPathNode()
	case "TRANSFORM_GROUP":
		return t.AsTransformGroupNode()
	case "VECTOR":
		return t.AsVectorNode()
	case "WASHI_TAPE":
		return t.AsWashiTapeNode()
	case "WIDGET":
		return t.AsWidgetNode()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

