// CallbackInitiator sends OpenAPI callback requests to target URLs.
// Modeled on the generated Client, but with no stored Server -- the full
// target URL is provided per-call by the caller (typically discovered
// from a callback expression on the parent operation's request body,
// e.g. `{$request.body#/callbackUrl}`).
type CallbackInitiator struct {
	// Doer for performing requests, typically a *http.Client with any
	// customized settings, such as certificate chains.
	Client HttpRequestDoer

	// A list of callbacks for modifying requests which are generated before sending over
	// the network.
	RequestEditors []RequestEditorFn
}

// CallbackInitiatorOption allows setting custom parameters during construction.
type CallbackInitiatorOption func(*CallbackInitiator) error

// NewCallbackInitiator creates a new CallbackInitiator with reasonable defaults.
func NewCallbackInitiator(opts ...CallbackInitiatorOption) (*CallbackInitiator, error) {
	initiator := CallbackInitiator{}
	for _, o := range opts {
		if err := o(&initiator); err != nil {
			return nil, err
		}
	}
	if initiator.Client == nil {
		initiator.Client = &http.Client{}
	}
	return &initiator, nil
}

// WithCallbackHTTPClient allows overriding the default Doer, which is
// automatically created using http.Client. This is useful for tests.
func WithCallbackHTTPClient(doer HttpRequestDoer) CallbackInitiatorOption {
	return func(p *CallbackInitiator) error {
		p.Client = doer
		return nil
	}
}

// WithCallbackRequestEditorFn allows setting up a callback function, which
// will be called right before sending the callback request. This can be
// used to mutate the request, e.g. to add signature headers.
func WithCallbackRequestEditorFn(fn RequestEditorFn) CallbackInitiatorOption {
	return func(p *CallbackInitiator) error {
		p.RequestEditors = append(p.RequestEditors, fn)
		return nil
	}
}

func (p *CallbackInitiator) applyCallbackEditors(ctx context.Context, req *http.Request, additionalEditors []RequestEditorFn) error {
	for _, r := range p.RequestEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	for _, r := range additionalEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	return nil
}

// CallbackInitiatorInterface is the interface specification for the callback initiator.
type CallbackInitiatorInterface interface {
	// DevModeStatusUpdateWithBody fires the devModeStatusUpdate callback with any body
	DevModeStatusUpdateWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	DevModeStatusUpdate(ctx context.Context, targetURL string, body DevModeStatusUpdateJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)

	// FileCommentWithBody fires the fileComment callback with any body
	FileCommentWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	FileComment(ctx context.Context, targetURL string, body FileCommentJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)

	// FileDeleteWithBody fires the fileDelete callback with any body
	FileDeleteWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	FileDelete(ctx context.Context, targetURL string, body FileDeleteJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)

	// FileUpdateWithBody fires the fileUpdate callback with any body
	FileUpdateWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	FileUpdate(ctx context.Context, targetURL string, body FileUpdateJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)

	// FileVersionUpdateWithBody fires the fileVersionUpdate callback with any body
	FileVersionUpdateWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	FileVersionUpdate(ctx context.Context, targetURL string, body FileVersionUpdateJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)

	// LibraryPublishWithBody fires the libraryPublish callback with any body
	LibraryPublishWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	LibraryPublish(ctx context.Context, targetURL string, body LibraryPublishJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)

	// PingWithBody fires the ping callback with any body
	PingWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	Ping(ctx context.Context, targetURL string, body PingJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)
}

func (p *CallbackInitiator) DevModeStatusUpdateWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewDevModeStatusUpdateCallbackRequestWithBody(targetURL, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := p.applyCallbackEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return p.Client.Do(req)
}

